 ? 'The respondents chose to participate and were visitors to a sports website, so the sample is unlikely to be representative of the city\'s residents, regardless of its size.'
 : 'The percent is not reliable because the poll did not report a margin of error.';

const vals=[0,1,2,3,4], freq=[3,5,7,4,1];
const n=freq.reduce((a,b)=>a+b,0), total=vals.reduce((a,v,i)=>a+v*freq[i],0);
// median of n+1 values: (n+2)/2-th value; find it from cumulative counts (x may be any value; check it doesn't move the median)
const pos=(n+2)/2; let cum=0, med=null;
for(let i=0;i<vals.length;i++){cum+=freq[i]; if(cum>=pos){med=vals[i];break}}
const x=med*(n+1)-total;
// x>=med so the median position is unaffected by x
return x;

